<?php declare(strict_types=1);
namespace App\Repositories;
use App\Database\Connection;use App\Security\Security;use App\Services\Events\EventRepositoryInterface;use App\Services\Notifications\NotificationOutbox;use DateTimeImmutable;use DomainException;use PDO;use PDOException;
final class EventRepository extends Repository implements EventRepositoryInterface{
 public function __construct(Connection $database){parent::__construct($database);}
 public function publicEvents():array{return $this->connection()->query("SELECT events.public_id,events.title,events.slug,events.description,events.event_date,events.start_time,events.end_time,events.venue,events.online_url,events.registration_deadline,events.capacity,events.fee,events.fee_currency,events.eligibility,events.registration_access,events.banner_path,types.name AS type_name,(SELECT COUNT(*) FROM event_registrations registrations WHERE registrations.event_id=events.id AND registrations.status IN ('registered','attended')) AS registration_count FROM events INNER JOIN event_types types ON types.id=events.event_type_id AND types.active=1 WHERE events.status='published' AND events.deleted_at IS NULL ORDER BY events.event_date,events.start_time,events.title")->fetchAll();}
 public function publicEvent(string $slug):?array{$statement=$this->connection()->prepare("SELECT events.public_id,events.title,events.slug,events.description,events.event_date,events.start_time,events.end_time,events.venue,events.online_url,events.registration_deadline,events.capacity,events.fee,events.fee_currency,events.eligibility,events.registration_access,events.banner_path,types.name AS type_name,(SELECT COUNT(*) FROM event_registrations registrations WHERE registrations.event_id=events.id AND registrations.status IN ('registered','attended')) AS registration_count FROM events INNER JOIN event_types types ON types.id=events.event_type_id AND types.active=1 WHERE events.slug=:slug AND events.status='published' AND events.deleted_at IS NULL LIMIT 1");$statement->execute(['slug'=>$slug]);$row=$statement->fetch();return is_array($row)?$row:null;}
 public function memberRegistrations(int $userId):array{$statement=$this->connection()->prepare('SELECT registrations.public_id,registrations.registration_reference,registrations.status,registrations.registered_at,events.title,events.slug,events.event_date FROM event_registrations registrations INNER JOIN events ON events.id=registrations.event_id WHERE registrations.user_id=:user ORDER BY events.event_date DESC');$statement->execute(['user'=>$userId]);return $statement->fetchAll();}
 public function register(?int $userId,string $eventPublicId,array $data,string $reference,DateTimeImmutable $now):array{
  try{return $this->database->transaction(function(PDO $db)use($userId,$eventPublicId,$data,$reference,$now):array{$event=$db->prepare("SELECT * FROM events WHERE public_id=:id AND status='published' AND deleted_at IS NULL LIMIT 1 FOR UPDATE");$event->execute(['id'=>$eventPublicId]);$row=$event->fetch();if(!is_array($row))throw new DomainException('This event is unavailable for registration.');$stamp=$this->date($now);if($row['registration_deadline']!==null&&$row['registration_deadline']<$stamp)throw new DomainException('Registration for this event has closed.');if($row['event_date']<$now->format('Y-m-d'))throw new DomainException('This event has already taken place.');
   $email=strtolower((string)$data['email']);if($userId!==null){$account=$db->prepare("SELECT users.email FROM users INNER JOIN members ON members.user_id=users.id AND members.status='active' WHERE users.id=:id AND users.status='active' AND users.email_verified_at IS NOT NULL LIMIT 1");$account->execute(['id'=>$userId]);$accountEmail=$account->fetchColumn();if($row['registration_access']==='member'&&$accountEmail===false)throw new DomainException('Active membership is required for this event.');if($accountEmail===false){$user=$db->prepare("SELECT email FROM users WHERE id=:id AND status='active' AND email_verified_at IS NOT NULL LIMIT 1");$user->execute(['id'=>$userId]);$accountEmail=$user->fetchColumn();}if($accountEmail===false)throw new DomainException('An active verified account is required.');$email=strtolower((string)$accountEmail);}elseif($row['registration_access']==='member')throw new DomainException('Sign in with an active member account to register.');
   if($row['capacity']!==null){$count=$db->prepare("SELECT COUNT(*) FROM event_registrations WHERE event_id=:event AND status IN ('registered','attended')");$count->execute(['event'=>$row['id']]);if((int)$count->fetchColumn()>=(int)$row['capacity'])throw new DomainException('This event has reached capacity.');}
   $publicId=Security::uuidV4();$insert=$db->prepare("INSERT INTO event_registrations (public_id,event_id,user_id,registration_reference,registrant_name,registrant_email,registrant_phone,status,registered_at,created_at,updated_at) VALUES (:public_id,:event,:user,:reference,:name,:email,:phone,'registered',:now,:now,:now)");$insert->execute(['public_id'=>$publicId,'event'=>$row['id'],'user'=>$userId,'reference'=>$reference,'name'=>$data['name'],'email'=>$email,'phone'=>$data['phone'],'now'=>$stamp]);$this->audit($db,$userId,'event.registration_created','event_registration',$publicId,['event_public_id'=>$eventPublicId],$now);NotificationOutbox::enqueue($db,'event.registration',$publicId,$userId,$email,'events','Event registration confirmed','Your event registration has been recorded. Reference: '.$reference,'/events/'.$row['slug'],array_values(array_filter(['email',$userId!==null?'in_app':null])),$now);return ['public_id'=>$publicId,'registration_reference'=>$reference,'status'=>'registered'];
  });}catch(PDOException $e){if($e->getCode()==='23000')throw new DomainException('You are already registered for this event.');throw $e;}}
 public function adminDashboard():array{$db=$this->connection();$types=$db->query('SELECT public_id,name FROM event_types WHERE active=1 ORDER BY display_order,name')->fetchAll();$events=$db->query("SELECT events.public_id,events.title,events.slug,events.description,events.event_date,events.start_time,events.end_time,events.venue,events.online_url,events.registration_deadline,events.capacity,events.fee,events.fee_currency,events.eligibility,events.registration_access,events.banner_path,events.status,types.public_id AS type_public_id,types.name AS type_name,(SELECT COUNT(*) FROM event_registrations r WHERE r.event_id=events.id AND r.status IN ('registered','attended')) AS registration_count FROM events INNER JOIN event_types types ON types.id=events.event_type_id WHERE events.deleted_at IS NULL ORDER BY events.event_date DESC,events.title")->fetchAll();return compact('types','events');}
 public function attendees(string $eventPublicId):?array{$db=$this->connection();$event=$db->prepare('SELECT public_id,title,event_date,capacity,status FROM events WHERE public_id=:id AND deleted_at IS NULL LIMIT 1');$event->execute(['id'=>$eventPublicId]);$row=$event->fetch();if(!is_array($row))return null;$items=$db->prepare('SELECT public_id,registration_reference,registrant_name,registrant_email,registrant_phone,status,registered_at FROM event_registrations WHERE event_id=(SELECT id FROM events WHERE public_id=:id) ORDER BY registered_at,id');$items->execute(['id'=>$eventPublicId]);return ['event'=>$row,'items'=>$items->fetchAll()];}
 public function saveEvent(int $actor,?string $publicId,array $data):string{try{return $this->database->transaction(function(PDO $db)use($actor,$publicId,$data):string{$type=$db->prepare('SELECT id FROM event_types WHERE public_id=:id AND active=1 LIMIT 1');$type->execute(['id'=>$data['event_type']]);$typeId=$type->fetchColumn();if($typeId===false)throw new DomainException('The selected event type is unavailable.');$created=$publicId===null;$publicId??=Security::uuidV4();$params=['type'=>$typeId,'actor'=>$actor,'title'=>$data['title'],'slug'=>$data['slug'],'description'=>$data['description'],'event_date'=>$data['event_date'],'start_time'=>$data['start_time'],'end_time'=>$data['end_time'],'venue'=>$data['venue'],'online_url'=>$data['online_url'],'deadline'=>$data['registration_deadline'],'capacity'=>$data['capacity'],'fee'=>$data['fee'],'currency'=>$data['fee_currency'],'eligibility'=>$data['eligibility'],'access'=>$data['registration_access'],'banner'=>$data['banner_path'],'status'=>$data['status']];if($created){$params['public_id']=$publicId;$db->prepare('INSERT INTO events (public_id,event_type_id,created_by_user_id,title,slug,description,event_date,start_time,end_time,venue,online_url,registration_deadline,capacity,fee,fee_currency,eligibility,registration_access,banner_path,status) VALUES (:public_id,:type,:actor,:title,:slug,:description,:event_date,:start_time,:end_time,:venue,:online_url,:deadline,:capacity,:fee,:currency,:eligibility,:access,:banner,:status)')->execute($params);}else{$params['public_id']=$publicId;$update=$db->prepare('UPDATE events SET event_type_id=:type,title=:title,slug=:slug,description=:description,event_date=:event_date,start_time=:start_time,end_time=:end_time,venue=:venue,online_url=:online_url,registration_deadline=:deadline,capacity=:capacity,fee=:fee,fee_currency=:currency,eligibility=:eligibility,registration_access=:access,banner_path=:banner,status=:status WHERE public_id=:public_id AND deleted_at IS NULL');unset($params['actor']);$update->execute($params);if($update->rowCount()===0){$exists=$db->prepare('SELECT id FROM events WHERE public_id=:id AND deleted_at IS NULL');$exists->execute(['id'=>$publicId]);if($exists->fetchColumn()===false)throw new DomainException('Event not found.');}}$this->audit($db,$actor,$created?'event.created':'event.updated','event',$publicId,['status'=>$data['status']],new DateTimeImmutable('now'));return $publicId;});}catch(PDOException $e){if($e->getCode()==='23000')throw new DomainException('Event title conflicts with an existing event slug.');throw$e;}}
 public function cancelEvent(int $actor,string $publicId,DateTimeImmutable $now):void{$this->database->transaction(function(PDO$db)use($actor,$publicId,$now):void{$s=$db->prepare("UPDATE events SET status='cancelled' WHERE public_id=:id AND deleted_at IS NULL AND status<>'cancelled'");$s->execute(['id'=>$publicId]);if($s->rowCount()===0)throw new DomainException('Event is missing or already cancelled.');$this->audit($db,$actor,'event.cancelled','event',$publicId,[],$now);});}
 public function cancelRegistration(int $actor,string $eventPublicId,string $registrationPublicId,DateTimeImmutable $now):void{$this->database->transaction(function(PDO$db)use($actor,$eventPublicId,$registrationPublicId,$now):void{$registration=$db->prepare("SELECT registrations.id FROM event_registrations registrations INNER JOIN events ON events.id=registrations.event_id AND events.public_id=:event WHERE registrations.public_id=:registration AND registrations.status='registered' LIMIT 1 FOR UPDATE");$registration->execute(['event'=>$eventPublicId,'registration'=>$registrationPublicId]);$id=$registration->fetchColumn();if($id===false)throw new DomainException('Registration cannot be cancelled.');$s=$db->prepare("UPDATE event_registrations SET status='cancelled',cancelled_at=:now WHERE id=:id AND status='registered'");$s->execute(['now'=>$this->date($now),'id'=>$id]);if($s->rowCount()===0)throw new DomainException('Registration cannot be cancelled.');$this->audit($db,$actor,'event.registration_cancelled','event_registration',$registrationPublicId,['event_public_id'=>$eventPublicId],$now);});}
 public function recordAttendance(int $actor,string $eventPublicId,string $registrationPublicId,DateTimeImmutable $now):array{return $this->database->transaction(function(PDO$db)use($actor,$eventPublicId,$registrationPublicId,$now):array{$s=$db->prepare("SELECT registrations.id,registrations.status FROM event_registrations registrations INNER JOIN events ON events.id=registrations.event_id AND events.status<>'cancelled' WHERE events.public_id=:event AND registrations.public_id=:registration LIMIT 1 FOR UPDATE");$s->execute(['event'=>$eventPublicId,'registration'=>$registrationPublicId]);$r=$s->fetch();if(!is_array($r))throw new DomainException('Registration not found or event cancelled.');$existing=$db->prepare('SELECT public_id,checked_in_at FROM event_attendance WHERE event_registration_id=:id LIMIT 1');$existing->execute(['id'=>$r['id']]);$attendance=$existing->fetch();if(is_array($attendance))return ['idempotent'=>true,'attendance'=>$attendance];if($r['status']!=='registered')throw new DomainException('Only an active registration can be checked in.');$attendanceId=Security::uuidV4();$stamp=$this->date($now);$db->prepare("INSERT INTO event_attendance (public_id,event_registration_id,checked_in_by_user_id,check_in_method,checked_in_at) VALUES (:public_id,:registration,:actor,'manual',:now)")->execute(['public_id'=>$attendanceId,'registration'=>$r['id'],'actor'=>$actor,'now'=>$stamp]);$db->prepare("UPDATE event_registrations SET status='attended',updated_at=:now WHERE id=:id")->execute(['now'=>$stamp,'id'=>$r['id']]);$this->audit($db,$actor,'event.attendance_recorded','event_registration',$registrationPublicId,['event_public_id'=>$eventPublicId,'method'=>'manual'],$now);return ['idempotent'=>false,'attendance'=>['public_id'=>$attendanceId,'checked_in_at'=>$stamp]];});}
 private function audit(PDO$db,?int$actor,string$action,string$type,string$id,array$values,DateTimeImmutable$now):void{$db->prepare("INSERT INTO audit_logs (actor_user_id,action,auditable_type,auditable_id,description,new_values,request_id,created_at) VALUES (:actor,:action,:type,:id,'An event workflow action was completed.',:values,:request_id,:created_at)")->execute(['actor'=>$actor,'action'=>$action,'type'=>$type,'id'=>$id,'values'=>$values?json_encode($values,JSON_THROW_ON_ERROR):null,'request_id'=>bin2hex(random_bytes(16)),'created_at'=>$this->date($now)]);}private function date(DateTimeImmutable$d):string{return$d->format('Y-m-d H:i:s.u');}
}
